    function request(action) {
      return fetch(CONFIG_URL, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(action || {}),
      }).then(function (r) {
        return r.json().catch(function () { return { ok: false, error: 'HTTP ' + r.status } })
      })
    }

    function useSnapshot(interval) {
      var s = React.useState(null)
      var snap = s[0]
      var setSnap = s[1]
      var e = React.useState(null)
      var error = e[0]
      var setError = e[1]
      var l = React.useState(true)
      var loading = l[0]
      var setLoading = l[1]
      function load() {
        return fetch(CONFIG_URL, { cache: 'no-store' })
          .then(function (r) { return r.json() })
          .then(function (j) { if (j && j.ok !== false) { setSnap(j); setError(null) } else { setError((j && j.error) || '读取快照失败') } })
          .catch(function (err) { setError(err.message || String(err)) })
          .finally(function () { setLoading(false) })
      }
      React.useEffect(function () {
        var alive = true
        load()
        var t = setInterval(function () { if (alive) load() }, interval || 6000)
        return function () { alive = false; clearInterval(t) }
      }, [])
      return { snap: snap, error: error, loading: loading, reload: load }
    }

    function useRunner(reload, setToast) {
      var busyState = React.useState(false)
      var busy = busyState[0]
      var setBusy = busyState[1]
      function run(action, okMsg) {
        setBusy(true)
        return request(action).then(function (j) {
          if (j && j.canceled) return j
          if (!j || j.ok === false) {
            setToast({ msg: (j && j.error) || '操作失败', bad: true })
            throw new Error((j && j.error) || '操作失败')
          }
          if (okMsg) setToast({ msg: okMsg })
          if (reload) reload()
          return j
        }).catch(function (e) {
          if (!e.__shown) setToast({ msg: e.message || String(e), bad: true })
          throw e
        }).finally(function () { setBusy(false) })
      }
      return { busy: busy, run: run }
    }

