        threads: String(cfgRt.threads || 0), ngl: String(cfgRt.ngl ?? -1), tiered: cfgRt.tiered !== false, ctx: String(cfgRt.ctx || 65536),
        flashAttn: cfgRt.flashAttn || 'auto', kvCache: cfgRt.kvCache || 'f16',
        batch: String(cfgRt.batch || 512), ubatch: String(cfgRt.ubatch || 256), parallel: String(cfgRt.parallel || 1),
        mmap: cfgRt.mmap !== false, mlock: Boolean(cfgRt.mlock), warmup: cfgRt.warmup !== false,
        extraArgs: cfgRt.extraArgs || '', path: cfgRt.path || '',
